-- =============================================================
-- SmartBus Maharashtra - Database Schema and Seed Data
-- Database: smartbus_mh
-- =============================================================

CREATE DATABASE IF NOT EXISTS smartbus_mh CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smartbus_mh;


CREATE TABLE IF NOT EXISTS users (
    user_id     INT AUTO_INCREMENT PRIMARY KEY,
    name        VARCHAR(100) NOT NULL,
    email       VARCHAR(150) NOT NULL UNIQUE,
    mobile      VARCHAR(15)  NOT NULL,
    password    VARCHAR(255) NOT NULL,
    role        ENUM('user','admin') DEFAULT 'user',
    is_active   TINYINT(1)  DEFAULT 1,
    created_at  DATETIME    DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS buses (
    bus_id          INT AUTO_INCREMENT PRIMARY KEY,
    service_number  VARCHAR(20)  NOT NULL UNIQUE,
    bus_number      VARCHAR(20)  NOT NULL UNIQUE,
    bus_name        VARCHAR(100) NOT NULL,
    bus_type        ENUM('Ordinary','Express','AC Seater','Semi Sleeper','Sleeper') NOT NULL,
    total_seats     INT          NOT NULL DEFAULT 40,
    status          ENUM('Active','Inactive') DEFAULT 'Active'
);

CREATE TABLE IF NOT EXISTS routes (
    route_id    INT AUTO_INCREMENT PRIMARY KEY,
    source      VARCHAR(100) NOT NULL,
    destination VARCHAR(100) NOT NULL,
    distance    DECIMAL(8,2) NOT NULL DEFAULT 0,
    duration    VARCHAR(20)  NOT NULL,
    fare        DECIMAL(10,2) NOT NULL
);

CREATE TABLE IF NOT EXISTS schedules (
    schedule_id    INT AUTO_INCREMENT PRIMARY KEY,
    bus_id         INT NOT NULL,
    route_id       INT NOT NULL,
    travel_date    DATE NOT NULL,
    departure_time TIME NOT NULL,
    arrival_time   TIME NOT NULL,
    FOREIGN KEY (bus_id)   REFERENCES buses(bus_id)   ON DELETE CASCADE,
    FOREIGN KEY (route_id) REFERENCES routes(route_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS bookings (
    booking_id      INT AUTO_INCREMENT PRIMARY KEY,
    booking_code    VARCHAR(25) NOT NULL UNIQUE,
    user_id         INT NOT NULL,
    schedule_id     INT NOT NULL,
    booking_date    DATETIME    DEFAULT CURRENT_TIMESTAMP,
    total_amount    DECIMAL(10,2) NOT NULL,
    payment_method  ENUM('UPI','Card','Net Banking','Cash') DEFAULT 'Cash',
    payment_status  ENUM('Paid','Pending','Failed') DEFAULT 'Pending',
    booking_status  ENUM('Confirmed','Cancelled') DEFAULT 'Confirmed',
    FOREIGN KEY (user_id)     REFERENCES users(user_id)         ON DELETE CASCADE,
    FOREIGN KEY (schedule_id) REFERENCES schedules(schedule_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS booking_seats (
    booking_seat_id  INT AUTO_INCREMENT PRIMARY KEY,
    booking_id       INT NOT NULL,
    seat_number      VARCHAR(10)  NOT NULL,
    passenger_name   VARCHAR(100) NOT NULL,
    passenger_age    INT          NOT NULL,
    passenger_gender ENUM('Male','Female','Other') NOT NULL,
    passenger_mobile VARCHAR(15)  NOT NULL,
    FOREIGN KEY (booking_id) REFERENCES bookings(booking_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS payments (
    payment_id      INT AUTO_INCREMENT PRIMARY KEY,
    booking_id      INT NOT NULL,
    transaction_id  VARCHAR(40) NOT NULL UNIQUE,
    payment_method  ENUM('UPI','Card','Net Banking','Cash') NOT NULL,
    amount          DECIMAL(10,2) NOT NULL,
    payment_status  ENUM('Paid','Pending','Failed') DEFAULT 'Paid',
    paid_at         DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (booking_id) REFERENCES bookings(booking_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS tickets (
    ticket_id      INT AUTO_INCREMENT PRIMARY KEY,
    ticket_number  VARCHAR(25) NOT NULL UNIQUE,
    booking_id     INT NOT NULL,
    generated_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
    ticket_status  ENUM('Active','Cancelled') DEFAULT 'Active',
    FOREIGN KEY (booking_id) REFERENCES bookings(booking_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS contact_messages (
    message_id  INT AUTO_INCREMENT PRIMARY KEY,
    name        VARCHAR(100) NOT NULL,
    email       VARCHAR(150) NOT NULL,
    message     TEXT NOT NULL,
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP
);

